mermaidCode:
graph TD
    A[Atmosphere] --> B[Troposphere]
    B --> C[Stratosphere]
    C --> D[Mesosphere]
    D --> E[Thermosphere / Ionosphere]
    B:::tempDesc1
    C:::tempDesc2
    D:::tempDesc3
    E:::tempDesc4
    classDef tempDesc1 fill:#e0f7fa,stroke:#006064,stroke-width:1px;
    classDef tempDesc2 fill:#b2ebf2,stroke:#006064,stroke-width:1px;
    classDef tempDesc3 fill:#80deea,stroke:#006064,stroke-width:1px;
    classDef tempDesc4 fill:#4dd0e1,stroke:#006064,stroke-width:1px;
